Script.Workflow:
module UbuntuPalette;
using presentation::*;
using presentation::compositions::*;
using presentation::templates::*;
namespace ubuntuskin
{
  struct ColorPackage
  {
    WindowBackground : Color;
    SidebarBackground : Color;
    ViewBackground : Color;
    HeaderBackground : Color;
    InactiveHeaderBackground : Color;
    HeaderInk : Color;
    FrameBorder : Color;
    InactiveHeaderInk : Color;
    PopupBackground : Color;
    ControlAccent : Color;
    ControlAccentPressed : Color;
    Border : Color;
    Divider : Color;
    Ink : Color;
    DocumentInk : Color;
    SecondaryInk : Color;
    DisabledInk : Color;
    Accent : Color;
    AccentPressed : Color;
    Focus : Color;
    SelectedText : Color;
    SelectionBackground : Color;
    HoverSurface : Color;
    PressedSurface : Color;
    SelectedSurface : Color;
    CaptionButtonSurface : Color;
    InactiveCaptionButtonSurface : Color;
    CaptionButtonHovered : Color;
    CaptionButtonPressed : Color;
    Track : Color;
    KeytipBackground : Color;
    KeytipText : Color;
    EditorNormal : EditorColors;
    EditorHovered : EditorColors;
    EditorFocused : EditorColors;
    EditorBackdrop : EditorColors;
    EditorDisabled : EditorColors;
    ButtonNormal : ButtonColors;
    ButtonHovered : ButtonColors;
    ButtonPressed : ButtonColors;
    ButtonDisabled : ButtonColors;
    ComboNormal : ButtonColors;
    CheckedNormal : ButtonColors;
    CheckedHovered : ButtonColors;
    CheckedPressed : ButtonColors;
    CheckedDisabled : ButtonColors;
    ItemNormal : ButtonColors;
    ItemHovered : ButtonColors;
    ItemPressed : ButtonColors;
    ItemSelected : ButtonColors;
    ItemDisabled : ButtonColors;
    TabNormal : ButtonColors;
    TabHovered : ButtonColors;
    TabSelected : ButtonColors;
    HeaderActionNormal : ButtonColors;
    HeaderActionHovered : ButtonColors;
    HeaderActionPressed : ButtonColors;
    HeaderActionDisabled : ButtonColors;
    CommandNormal : ButtonColors;
    CommandHovered : ButtonColors;
    CommandPressed : ButtonColors;
    CommandOpen : ButtonColors;
    CommandSelected : ButtonColors;
    CommandDisabled : ButtonColors;
    ScrollHandleNormal : ButtonColors;
    ScrollHandleActive : ButtonColors;
    ScrollHandlePressed : ButtonColors;
    ScrollHandleDisabled : ButtonColors;
  }

  func FlatButtonColors(border : Color, face : Color, text : Color, bullet : Color) : ButtonColors
  {
    return { Border: border; G1: face; G2: face; Text: text; Bullet: bullet; };
  }

  func UnpaintedButtonColors(surface : Color, text : Color) : ButtonColors
  {
    return { HideBackground: true; Border: surface; G1: surface; G2: surface; Text: text; Bullet: text; };
  }

  func CreateDefaultColorPackage() : ColorPackage
  {
    var window = cast Color "#FAFAFA";
    var view = cast Color "#FFFFFF";
    var entry = cast Color "#EBEBEB";
    var border = cast Color "#C7C7C7";
    var ink = cast Color "#3D3D3D";
    var disabledInk = cast Color "#9B9B9B";
    var disabledFace = cast Color "#F5F5F5";
    var controlAccent = cast Color "#D34615";
    var accent = cast Color "#E95420";
    var focus = cast Color "#DB977F";
    var hover = cast Color "#DEDEDE";
    var buttonFace = cast Color "#E7E7E7";
    var pressed = cast Color "#C1C1C1";
    var selected = cast Color "#E4E4E4";
    var commandPressed = cast Color "#D6D6D6";

    return {
      WindowBackground: window;
      SidebarBackground: view;
      ViewBackground: view;
      HeaderBackground: entry;
      InactiveHeaderBackground: cast Color "#F0F0F0";
      HeaderInk: ink;
      FrameBorder: cast Color "#BDBDBD";
      InactiveHeaderInk: cast Color "#959595";
      PopupBackground: window;
      ControlAccent: controlAccent;
      ControlAccentPressed: cast Color "#AD3911";
      Border: border;
      Divider: cast Color "#E1E1E1";
      Ink: ink;
      DocumentInk: ink;
      SecondaryInk: cast Color "#6F6F6F";
      DisabledInk: disabledInk;
      Accent: accent;
      AccentPressed: cast Color "#BF4214";
      Focus: focus;
      SelectedText: cast Color "#6B4132";
      SelectionBackground: cast Color "#E4BAAB";
      HoverSurface: cast Color "#E2E2E2";
      PressedSurface: cast Color "#C5C5C5";
      SelectedSurface: selected;
      CaptionButtonSurface: cast Color "#DADADA";
      InactiveCaptionButtonSurface: cast Color "#E7E7E7";
      CaptionButtonHovered: cast Color "#CECECE";
      CaptionButtonPressed: pressed;
      Track: cast Color "#E2E2E2";
      KeytipBackground: cast Color "#323232";
      KeytipText: view;

      EditorNormal: { Border: entry; Background: entry; };
      EditorHovered: { Border: border; Background: entry; };
      EditorFocused: { Border: focus; Background: entry; };
      EditorBackdrop: { Border: disabledFace; Background: disabledFace; };
      EditorDisabled: { Border: disabledFace; Background: disabledFace; };

      ButtonNormal: FlatButtonColors(buttonFace, buttonFace, ink, ink);
      ButtonHovered: FlatButtonColors(hover, hover, ink, ink);
      ButtonPressed: FlatButtonColors(pressed, pressed, ink, ink);
      ButtonDisabled: FlatButtonColors(disabledFace, disabledFace, disabledInk, disabledInk);
      ComboNormal: FlatButtonColors(border, view, ink, ink);

      CheckedNormal: FlatButtonColors(cast Color "#D5D5D5", view, ink, view);
      CheckedHovered: FlatButtonColors(cast Color "#B5B5B5", window, ink, view);
      CheckedPressed: FlatButtonColors(cast Color "#B5B5B5", cast Color "#F0F0F0", ink, view);
      CheckedDisabled: FlatButtonColors(hover, disabledFace, disabledInk, window);

      ItemNormal: UnpaintedButtonColors(view, ink);
      ItemHovered: FlatButtonColors(cast Color "#F7F7F7", cast Color "#F7F7F7", ink, ink);
      ItemPressed: FlatButtonColors(cast Color "#F0F0F0", cast Color "#F0F0F0", ink, ink);
      ItemSelected: FlatButtonColors(selected, selected, ink, ink);
      ItemDisabled: UnpaintedButtonColors(view, disabledInk);

      TabNormal: FlatButtonColors(border, window, ink, ink);
      TabHovered: FlatButtonColors(border, window, ink, ink);
      TabSelected: FlatButtonColors(cast Color "#F2A98F", window, ink, accent);

      HeaderActionNormal: FlatButtonColors(window, window, ink, ink);
      HeaderActionHovered: FlatButtonColors(border, hover, ink, ink);
      HeaderActionPressed: FlatButtonColors(accent, hover, ink, ink);
      HeaderActionDisabled: FlatButtonColors(window, window, disabledInk, disabledInk);

      CommandNormal: UnpaintedButtonColors(window, ink);
      CommandHovered: FlatButtonColors(border, disabledFace, ink, ink);
      CommandPressed: FlatButtonColors(border, commandPressed, ink, ink);
      CommandOpen: FlatButtonColors(cast Color "#BABABA", window, ink, ink);
      CommandSelected: FlatButtonColors(border, commandPressed, ink, controlAccent);
      CommandDisabled: UnpaintedButtonColors(window, disabledInk);

      ScrollHandleNormal: FlatButtonColors(cast Color "#898989", cast Color "#898989", ink, ink);
      ScrollHandleActive: FlatButtonColors(cast Color "#727272", cast Color "#727272", ink, ink);
      ScrollHandlePressed: FlatButtonColors(cast Color "#595959", cast Color "#595959", ink, ink);
      ScrollHandleDisabled: UnpaintedButtonColors(window, disabledInk);
    };
  }

  var ubuntuColors : ColorPackage = CreateDefaultColorPackage();

  func FindWindowTemplate(composition : GuiGraphicsComposition*) : GuiWindowTemplate*
  {
    var parent = composition.Parent;
    while (parent is not null)
    {
      if (var window : GuiWindowTemplate* = parent as GuiWindowTemplate*)
      {
        return window;
      }
      parent = parent.Parent;
    }
    return null;
  }

  /*
  * Calling GuiApplication::GetApplication().RefreshThemes will reload the new baseline document.
  */
  func CreateBaselineDocument() : DocumentModel^
  {
    var document = new DocumentModel^();
    var normal = new DocumentStyle^();
    normal.styles = new DocumentStyleProperties^();
    normal.styles.color = ubuntuColors.DocumentInk;
    document.styles["#Default-Override"] = normal;
    var selection = new DocumentStyle^();
    selection.styles = new DocumentStyleProperties^();
    selection.styles.color = ubuntuColors.SelectedText;
    selection.styles.backgroundColor = ubuntuColors.SelectionBackground;
    document.styles["#Selection-Override"] = selection;
    return document;
  }
}
